-- ==============================================
-- ARTICLE: El Árbol y el Viento (el-arbol-y-el-viento)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'el-arbol-y-el-viento';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'El Árbol y el Viento',
    'el-arbol-y-el-viento',
    $html$<h2>📜 Descripción de la Dinámica</h2><p><strong>El Árbol y el Viento</strong> es una profunda dinámica scout de sensibilización y confianza grupal. En ella, un participante se ubica relajado en el centro de un círculo compacto formado por sus compañeros y se deja mecer suavemente como el tronco de un árbol mecido por la brisa, experimentando la contención y el cuidado colectivo.</p><hr><h3>🎲 ¿Cómo se juega El Árbol y el Viento?</h3><ol><li><strong>El Círculo de Protección:</strong> Los participantes forman un círculo muy compacto, hombro con hombro, con los brazos flexionados hacia adelante y las palmas de las manos listas para brindar sostén.</li><li><strong>El Árbol en el Centro:</strong> Un participante se coloca en el centro con los pies firmes en el suelo, los brazos cruzados sobre el pecho o colgando relajados, y cierra los ojos. Debe mantener el cuerpo erguido pero relajado, confiando en sus compañeros.</li><li><strong>El Balanceo de la Brisa:</strong> Los integrantes del círculo empujan y reciben suavemente al participante del centro con toques delicados en la espalda y los hombros, meciéndolo de un lado a otro en un movimiento continuo y rítmico.</li><li><strong>Silencio y Clima de Confianza:</strong> La dinámica requiere un ambiente de silencio absoluto y respeto para permitir la concentración e introspección de quien está en el centro.</li><li><strong>Cierre y Evaluación:</strong> Cada participante pasa por el centro del círculo y, al finalizar, el grupo realiza una ronda de conversación para compartir sensaciones y emociones.</li></ol>$html$,
    'Una profunda dinámica scout de confianza donde un participante se deja mecer suavemente en el centro de un círculo fraterno.',
    '/uploads/actividad_elArbolYElViento.webp',
    'publicado',
    ARRAY['dinamica-de-confianza', 'afectividad', 'panolines', 'interior', 'exterior'],
    $json${"areas": ["afectividad", "sociabilidad", "carácter"], "lugares": ["Interior", "Exterior", "campo delimitado"], "cantidad": "06 participantes", "duracion": "15 minutos", "unidades": ["compañía", "tropa", "avanzada", "clan"], "descargas": [], "objetivos": ["Estimular la confianza", "Crear un clima de pertenencia", "Fomentar un entorno de confianza", "Introspección"], "materiales": ["Pañolines", "Sin Materiales"], "variaciones": "<b>El Bosque Soplado por el Viento:</b> Se forman varios círculos simultáneos de 5 a 6 participantes para que la dinámica sea más íntima y todos los scouts pasen al centro en menor tiempo.<br/><br/>\n\n<b>Balanceo con Pañolín:</b> El participante del centro utiliza su <b>pañolín</b> a modo de venda para reforzar la desinhibición y el abandono voluntario del control visual.<br/><br/>\n\n<b>Cálida Recepción:</b> Al terminar el mecido, el círculo se estrecha lentamente abrazando de forma coordinada al participante del centro antes de que abra los ojos.<br/><br/>", "recomendaciones": "<b>Seguridad Ante Todo:</b> Asegurar que las palmas de los compañeros del círculo estén siempre listas y firmes a la altura del pecho y espalda. Queda estrictamente prohibido hacer movimientos bruscos o soltar al participante.<br/><br/>\n\n<b>Silencio y Concentración:</b> Crear una atmósfera de tranquilidad previa. El tono de voz del dirigente facilitador debe ser pausado y sereno.<br/><br/>\n\n<b>Participación Voluntaria:</b> Respetar a aquellos participantes que sientan timidez inicial, permitiéndoles primero ser parte del círculo exterior antes de pasar al centro.<br/><br/>", "justificacion_areas": "El Árbol y el Viento fortalece la afectividad al brindar un espacio seguro para vencer temores y elevar la confianza en uno mismo. Desarrolla la sociabilidad al afianzar la empatía y la contención cuidadosa entre iguales, y ejercita el carácter al cultivar la serenidad, la desinhibición y la desinteresada entrega al grupo.", "objetivos_educativos": [{"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Compañía", "como_se_cumple": "Afianzando una imagen corporal y emocional positiva a través del apoyo colectivo."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Fomentando un ambiente de contención mutua y cuidado solidario."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Viviendo la experiencia con tranquilidad y espontaneidad en el grupo."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Fomentando un clima de distensión y apertura dialogante."}, {"id": "3a35ddd8-f6dc-4e00-a04d-107a0825bd99", "area": "Carácter", "texto": "Escucho las críticas que me hacen los demás y reflexiono sobre ellas.", "unidad": "Compañía", "como_se_cumple": "Desarrollando serenidad emocional al cerrar los ojos y confiar en la unidad."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Aceptando la entrega con deportividad y serenidad de carácter."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Expresando lo vivido con sinceridad y sentido del humor al finalizar el ejercicio."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Liderando con empatía la contención del grupo para generar seguridad absoluta."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "area": "Carácter", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "unidad": "Tropa", "como_se_cumple": "Aceptando mis vulnerabilidades y confiando en el sostén fraterno de la patrulla."}, {"id": "8f0eb7d9-c291-44f3-9551-4330c19e0cc2", "area": "Carácter", "texto": "Conozco mis posibilidades y limitaciones, aceptándome con capacidad de autocrítica y manteniendo a la vez una buena imagen de mí mismo.", "unidad": "Clan", "como_se_cumple": "Cultivando la madurez afectiva y la aceptación serena de mis posibilidades personales."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Respetando la libertad y el ritmo emocional de cada participante."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Afrontando el reto de soltarse con una actitud serena y positiva."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Ofreciendo un soporte firme y respetuoso a todos los miembros de la patrulla."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "area": "Sociabilidad", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "unidad": "Clan", "como_se_cumple": "Ejerciendo el servicio solidario garantizando el bienestar colectivo de los caminantes."}, {"id": "c380e11a-571d-4617-924c-aa933ae30138", "area": "Carácter", "texto": "Soy capaz de criticarme.", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo la autoestima al experimentar el cuidado y la protección de mis pares."}, {"id": "d716bdfb-2fea-4b96-9a46-b86d66692d45", "area": "Carácter", "texto": "Enfrento la vida con alegría y sentido del humor.", "unidad": "Clan", "como_se_cumple": "Reflexionando sobre la confianza con madurez, templanza y optimismo."}, {"id": "dea08f50-52d5-4d87-ad7f-b7dbbb2702fc", "area": "Carácter", "texto": "Me acepto tal como soy, sin dejar de mirarme críticamente.", "unidad": "Avanzada", "como_se_cumple": "Profundizando la confianza interior y el autocontrol emocional ante el grupo."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Participando activamente en la creación de un espacio de confianza y respeto."}]}$json$::jsonb
  );

